// Pass only when someone other than the requester approved the PR's latest commit.
export interface Pr { user: { login: string }; body: string | null }
export interface Review { state: string; commit_id: string; user: { login: string; type: string } }

const AGENT_BOTS = new Set(["rhino-ai-agents[bot]"]);
const REQUESTED_BY = /^Requested-by:\s*@?([A-Za-z0-9-]+)\s*$/m;
const DECISIVE = new Set(["APPROVED", "CHANGES_REQUESTED", "DISMISSED"]); // a later plain comment doesn't undo an approval

export class MissingRequester extends Error {}

export function requesters(pr: Pr, commitAuthors: string[], bodyEditors: string[]): Set<string> {
  const people = [pr.user.login];
  if (AGENT_BOTS.has(pr.user.login)) {
    const found = REQUESTED_BY.exec(pr.body ?? "")?.[1];
    if (!found) throw new MissingRequester("Agent PR without a 'Requested-by:' line; failing closed.");
    people.push(found);
  }
  // Anyone who pushed code or rewrote the PR body is part of the change, so they can't approve it.
  return new Set([...people, ...commitAuthors, ...bodyEditors].map((p) => p.toLowerCase()));
}

export function independentApprovers(reviews: Review[], headSha: string, people: Set<string>): Set<string> {
  const latest = new Map<string, Review>();
  for (const review of reviews) { // the API lists oldest first; keep each reviewer's last decisive review
    if (DECISIVE.has(review.state)) latest.set(review.user.login.toLowerCase(), review);
  }
  return new Set([...latest].filter(([login, review]) =>
    review.state === "APPROVED"
    && review.commit_id === headSha
    && review.user.type === "User" // approvals from apps never count
    && !people.has(login)).map(([login]) => login));
}
EOF

cat > check-pr.ts <<'EOF'
// Runs the check on one PR snapshot, the way the GitHub job would after reading the API.
import { readFileSync } from "node:fs";
import { independentApprovers, MissingRequester, requesters } from "./independent-approval.ts";

const file = process.argv[2];
const { pr, headSha, commitAuthors, bodyEditors, reviews } = JSON.parse(readFileSync(file, "utf8"));
try {
  const people = requesters(pr, commitAuthors, bodyEditors);
  const ok = independentApprovers(reviews, headSha, people);
  console.log(`${file}: requesters ${[...people].join(", ")}`);
  console.log(ok.size ? `PASS  independent approval from ${[...ok].join(", ")}` : "FAIL  no approval from someone outside the requesters on the latest commit");
  process.exitCode = ok.size ? 0 : 1;
} catch (error) {
  if (!(error instanceof MissingRequester)) throw error;
  console.log(`${file}: FAIL  ${error.message}`);
  process.exitCode = 1;
}
EOF

