import { test } from "node:test";
import assert from "node:assert/strict";

// IMPL lets you run the same tests against another version of the check.
const impl = await import(process.env.IMPL ?? "./independent-approval.ts");
const agentPr = { user: { login: "rhino-ai-agents[bot]" }, body: "Adds the card.\n\nRequested-by: @sean" };
const approve = (login: string, commit = "c3", type = "User") => ({ state: "APPROVED", commit_id: commit, user: { login, type } });
const pass = (pr: object, reviews: object[], authors: string[] = ["rhino-ai-agents[bot]"], editors: string[] = []) =>
  impl.independentApprovers(reviews, "c3", impl.requesters(pr, authors, editors)).size > 0;

test("a human PR approved by a teammate passes", () => {
  assert.equal(pass({ user: { login: "sean" }, body: "" }, [approve("dana")], ["sean"]), true);
});
test("an agent PR approved only by its requester fails", () => {
  assert.equal(pass(agentPr, [approve("sean")]), false);
});
test("the requester edits the body, then approves: fails", () => {
  const edited = { ...agentPr, body: "Adds the card.\n\nRequested-by: @dana" };
  assert.equal(pass(edited, [approve("sean")], undefined, ["sean"]), false);
});
test("an approval on an older commit fails", () => {
  assert.equal(pass(agentPr, [approve("dana", "c2")]), false);
});
test("a bot approval is ignored", () => {
  assert.equal(pass(agentPr, [approve("byte-review[bot]", "c3", "Bot")]), false);
});
test("a reviewer who pushed a fix is not independent", () => {
  assert.equal(pass(agentPr, [approve("dana")], ["rhino-ai-agents[bot]", "dana"]), false);
});
test("an agent PR without a Requested-by line fails closed", () => {
  assert.throws(() => impl.requesters({ ...agentPr, body: "no line" }, [], []), impl.MissingRequester);
});
